def-hyp[predicate](
    list-partial(
        Type.annotation(@x, T@Set.ctxt.T),
        Set.mem(x, S@Topology.ctxt.S),
        Type.annotation(@U, Set(T@Set.ctxt.T))
    ),
    Topology.neighborhood(U, x),
    Logic.exists-typed(
        @O,
        Set(T@Set.ctxt.T),
        Logic.and(Logic.and(Set.mem(O, τ@Topology.ctxt.tau), Set.mem(x, O)), Set.subset(O, U))
    )
)
